{
  "architect_scope": "one-R51-structural-factor-only",
  "proposal_mode": "counter_hypothesis",
  "qualitative_hypothesis": {
    "observed_bottleneck": "Source-labelled contract locking may cause inherited conformance framing to dominate terminal judgment and fragment behavioral coherence.",
    "causal_change": "Insert one mandatory provenance-erasing custody transition that preserves the complete executable artifact and its obligations while removing source identity before terminal authority.",
    "expected_effect": "Provenance-neutral whole-artifact judgment should jointly improve phase-shift adaptation and scan resistance by reducing inherited framing pressure.",
    "falsifier": "all-valid matched majority and strict-median contract, with no score"
  },
  "structural_mutation": {
    "change_count": 1,
    "factor": "mandatory provenance-erasing custody transition on the sole executable lineage",
    "before": "A source-labelled immutable contract boundary passes directly to terminal behavior-only authority alongside reintroduced common evidence.",
    "after": "A complete policy capsule passes through an irreversible source-identity erasure transition, after which terminal authority sees only the resulting executable state and treats its obligations indivisibly.",
    "why_structural": "The factor adds a mandatory state-transition node that changes evidence distinguishability, terminal visibility, and authority semantics; it is not role renaming, review fission, or candidate replication."
  },
  "mode_certificate": {
    "rejected_assumptions": [
      "A source-labelled contract boundary must remain visible and immutable through the terminal call.",
      "Conformance authority and behavioral authority should remain structurally separate.",
      "Reintroducing common external evidence at the terminal call improves policy judgment."
    ],
    "forbidden_inherited_mechanism": "immutable upstream contract locking followed by downstream behavior-only revision",
    "independent_replacement_principle": "provenance-neutral indivisible custody: resolve evidence once into one complete executable capsule, erase source identity at a mandatory custody transition, and expose only the resulting obligation-bearing artifact to terminal authority",
    "changed_behavioral_dimensions": [
      "phase-shift adaptation",
      "scan resistance"
    ],
    "counter_until_promotion": true
  },
  "candidate_structure": {
    "name": "Provenance-Neutral Custody Gate",
    "organization": "three-call sequential lineage with one mandatory provenance-erasing executable custody transition",
    "information_flow": "The first call receives all common evidence and forms one complete executable policy capsule without separating contract and behavioral authority. The second call consumes only that capsule, preserves its complete artifact and substantive obligations, and irreversibly erases the source identity attached to those obligations. The final call consumes only the resulting executable state, exercises indivisible authority over the single artifact without external evidence re-entry, and emits one policy.",
    "stages": [
      {
        "id": "provenance_neutral_custody",
        "mode": "sequential",
        "calls": [
          {
            "id": "compose_sourced_capsule",
            "role": "whole-artifact origin authority",
            "objective": "Resolve the supplied evidence into one complete executable policy capsule carrying its substantive obligations and evidence provenance without establishing separate contract and behavioral authority classes.",
            "inputs": [
              "task",
              "anchor_policy",
              "anchor_contract",
              "task_constraints",
              "candidate_hypothesis",
              "loop_structure"
            ],
            "output_type": "policy_capsule"
          },
          {
            "id": "erase_source_identity",
            "role": "provenance-erasing custody gate",
            "objective": "Consume compose_sourced_capsule, preserve its single complete executable artifact and substantive obligations, irreversibly remove which input supplied each obligation, and emit one provenance-neutral executable policy state.",
            "inputs": [
              "compose_sourced_capsule"
            ],
            "output_type": "executable_policy_state"
          },
          {
            "id": "exercise_unlabelled_authority",
            "role": "provenance-neutral terminal authority",
            "objective": "Consume erase_source_identity without common external evidence re-entry, treat the visible obligations as one indivisible authority surface, reconcile the single complete artifact for joint coherence, and emit one policy.",
            "inputs": [
              "erase_source_identity"
            ],
            "output_type": "policy"
          }
        ]
      }
    ],
    "final_call_id": "exercise_unlabelled_authority"
  },
  "compliance": {
    "one_structural_factor_only": true,
    "score_or_trace_content_used": false,
    "policy_code_emitted": false,
    "variants_sampling_or_best_of_n_emitted": false,
    "hardcoding_emitted": false
  }
}
